using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class ArrangeCathedralFurniture{
static Bounds BoundsOf(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static Transform Group(string n,Transform parent){var g=new GameObject(n);g.transform.SetParent(parent,false);Undo.RegisterCreatedObjectUndo(g,"Arrange cathedral furniture");return g.transform;}
static void Place(GameObject g,float x,float z,float floor){var b=BoundsOf(g);g.transform.position+=new Vector3(x-b.center.x,floor-b.min.y,z-b.center.z);}
public static string Run(){if(Application.isPlaying)throw new Exception("Edit mode required");var stage=UnityEngine.Object.FindObjectsByType<BattleStage>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(s=>s.name=="B2");if(stage.gameObject.scene.path!="Assets/Scenes/3DBattleScene.unity")throw new Exception("Wrong scene");if(stage.transform.Find("Cathedral Seating")!=null)throw new Exception("Already arranged");
var reference=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(t=>t.gameObject.scene==stage.gameObject.scene&&t.name=="Furns_Chair_7"&&t.parent==null).gameObject;
Vector3 scale=reference.transform.lossyScale;Quaternion rotation=reference.transform.rotation;float floor=BoundsOf(stage.transform.Find("Arena").gameObject).max.y;
var seating=Group("Cathedral Seating",stage.transform);int count=0;
for(int side=0;side<2;side++){var row=Group(side==0?"Left - 10 Chairs":"Right - 10 Chairs",seating);for(int i=0;i<10;i++){var chair=UnityEngine.Object.Instantiate(reference,row);chair.name="Chair "+(i+1).ToString("00");chair.transform.SetPositionAndRotation(Vector3.zero,rotation);chair.transform.localScale=scale;Place(chair,Mathf.Lerp(-24,24,i/9f),side==0?-18:18,floor);var b=BoundsOf(chair);if(b.min.x<-29||b.max.x>29||b.min.z<-29||b.max.z>29)throw new Exception("Chair outside boundary");count++;}}
string path=Directory.GetFiles("Assets/3DBattle/Boss2/Cathedral","*stone_pillar*.fbx",SearchOption.AllDirectories).Single().Replace('\\','/');var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Cathedral Pillar"};mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Path.ChangeExtension(path,".png")));mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Smoothness",.3f);AssetDatabase.CreateAsset(mat,"Assets/3DBattle/Boss2/Cathedral/StageAssets/Cathedral Pillar.mat");var pillars=Group("Cathedral Pillars",stage.transform);
for(int side=0;side<2;side++){var row=Group(side==0?"Left - 3 Pillars":"Right - 3 Pillars",pillars);for(int i=0;i<3;i++){var holder=Group("Pillar "+(i+1).ToString("00"),row);var model=(GameObject)PrefabUtility.InstantiatePrefab(asset);model.transform.SetParent(holder,false);var b=BoundsOf(holder.gameObject);holder.localScale*=45/b.size.y;Place(holder.gameObject,Mathf.Lerp(-22,22,i/2f),side==0?-42:42,floor);foreach(var r in holder.GetComponentsInChildren<Renderer>()){r.sharedMaterial=mat;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}b=BoundsOf(holder.gameObject);if(side==0?b.max.z>=-31:b.min.z<=31)throw new Exception("Pillar intersects boundary");}}
if(count!=20)throw new Exception("Chair count wrong");Undo.DestroyObjectImmediate(reference);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(stage.gameObject.scene);EditorSceneManager.SaveScene(stage.gameObject.scene);Selection.activeGameObject=seating.gameObject;
return "PASS: 20 chairs inside +/-29 using reference scale="+scale+" and rotation="+rotation.eulerAngles+"; 6 pillars entirely outside boundary, height45; reference scene chair removed; saved.";
}}
